        /* ==========================================================================
           DESIGN SYSTEM & VARIABLES
           ========================================================================== */
        :root {
            /* Dark Theme (Default) */
            --bg-base: #000000;
            --bg-surface: #0a0a0a;
            --bg-surface-hover: #171717;
            --bg-glass: rgba(10, 10, 10, 0.95);
            
            --border-subtle: rgba(255, 255, 255, 0.08);
            --border-strong: rgba(255, 255, 255, 0.15);
            --border-focus: rgba(255, 255, 255, 0.3);
            
            --text-primary: #ffffff;
            --text-secondary: #a1a1aa;
            --text-tertiary: #52525b;
            
            --primary: #ffffff;
            --primary-invert: #000000;
            --accent-1: #3b82f6;
            --accent-2: #8b5cf6;
            --gradient-accent: linear-gradient(135deg, var(--accent-1), var(--accent-2));
            
            --success: #22c55e;
            --warning: #eab308;
            --danger: #ef4444;
            
            --shadow-sm: 0 2px 8px rgba(0,0,0,0.4);
            --shadow-md: 0 8px 24px rgba(0,0,0,0.6);
            --shadow-lg: 0 16px 40px rgba(0,0,0,0.8);
            --shadow-glow: 0 0 20px rgba(59, 130, 246, 0.2);
            
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-xl: 24px;
            --radius-full: 9999px;
            
            --transition-fast: 0s;
            --transition-smooth: 0s;
        }

        [data-theme="light"] {
            --bg-base: #f8fafc;
            --bg-surface: #ffffff;
            --bg-surface-hover: #f1f5f9;
            --bg-glass: rgba(255, 255, 255, 0.95);
            
            --border-subtle: rgba(0, 0, 0, 0.06);
            --border-strong: rgba(0, 0, 0, 0.12);
            --border-focus: rgba(0, 0, 0, 0.3);
            
            --text-primary: #0f172a;
            --text-secondary: #64748b;
            --text-tertiary: #94a3b8;
            
            --primary: #0f172a;
            --primary-invert: #ffffff;
            
            --shadow-sm: 0 2px 8px rgba(0,0,0,0.04);
            --shadow-md: 0 8px 24px rgba(0,0,0,0.08);
            --shadow-lg: 0 16px 40px rgba(0,0,0,0.12);
            --shadow-glow: 0 0 20px rgba(59, 130, 246, 0.15);
        }

        /* ==========================================================================
           RESET & TYPOGRAPHY
           ========================================================================== */
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background-color: var(--bg-base);
            color: var(--text-primary);
            line-height: 1.5;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
            transition: background-color var(--transition-smooth), color var(--transition-smooth);
            overflow-x: hidden;
            padding-bottom: 120px; /* Space for live progress bar on mobile */
        }

        /* Subtle background mesh/glow */
        body::before {
            content: '';
            position: fixed;
            top: 0; left: 0; width: 100vw; height: 100vh;
            background: radial-gradient(circle at 15% 0%, rgba(59, 130, 246, 0.05) 0%, transparent 40%),
                        radial-gradient(circle at 85% 100%, rgba(139, 92, 246, 0.05) 0%, transparent 40%);
            pointer-events: none;
            z-index: -1;
        }

        h1, h2, h3, h4 { font-weight: 600; letter-spacing: -0.02em; }
        h1 { font-size: 2.5rem; line-height: 1.1; }
        h2 { font-size: 1.5rem; margin-bottom: 1.5rem; }
        h3 { font-size: 1.125rem; margin-bottom: 1rem; color: var(--text-primary); display: flex; align-items: center; gap: 0.5rem; }
        p { color: var(--text-secondary); }
        
        a { color: var(--text-secondary); text-decoration: none; transition: var(--transition-fast); }
        a:hover { color: var(--text-primary); }

        ul { list-style: none; }
        button { font-family: inherit; cursor: pointer; border: none; background: none; }

        /* ==========================================================================
           LAYOUT COMPONENTS
           ========================================================================== */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 2rem;
        }

        .glass-panel {
            background: var(--bg-surface);
            border: 1px solid var(--border-subtle);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-sm);
            position: relative;
            overflow: hidden;
            transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
        }

        /* ==========================================================================
           TOP NAVBAR
           ========================================================================== */
        .navbar {
            position: sticky;
            top: 0;
            z-index: 100;
            background: var(--bg-glass);
            
            -webkit-
            border-bottom: 1px solid var(--border-subtle);
            padding: 1rem 0;
        }

        .nav-content {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .logo-section {
            display: flex;
            align-items: center;
            gap: 0.75rem;
            font-weight: 700;
            font-size: 1.25rem;
            letter-spacing: -0.04em;
        }

        .logo-icon {
            width: 32px;
            height: 32px;
            background: var(--primary);
            color: var(--primary-invert);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.25rem;
        }

        .nav-links {
            display: flex;
            gap: 2rem;
        }

        .nav-links a {
            font-size: 0.875rem;
            font-weight: 500;
            position: relative;
            padding: 0.5rem 0;
        }

        .nav-links a.active {
            color: var(--text-primary);
        }

        .nav-links a.active::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 2px;
            background: var(--primary);
            border-radius: 2px;
        }

        .nav-actions {
            display: flex;
            align-items: center;
            gap: 1rem;
        }

        .icon-btn {
            color: var(--text-secondary);
            transition: color var(--transition-fast);
            display: flex;
            align-items: center;
            justify-content: center;
            width: 36px;
            height: 36px;
            border-radius: var(--radius-full);
            background: var(--bg-surface);
            border: 1px solid var(--border-subtle);
        }
        .icon-btn:hover {
            color: var(--text-primary);
            border-color: var(--border-strong);
        }

        .avatar {
            width: 36px;
            height: 36px;
            border-radius: var(--radius-full);
            background: var(--gradient-accent);
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: 600;
            font-size: 0.875rem;
            border: 2px solid var(--bg-base);
            cursor: pointer;
        }

        .btn-outline {
            background: transparent;
            border: 1px solid var(--border-strong);
            color: var(--text-primary);
            padding: 0.5rem 1rem;
            border-radius: var(--radius-md);
            font-weight: 500;
            cursor: pointer;
            transition: transform var(--transition-fast);
        }
        .btn-outline:hover {
            background: rgba(255, 255, 255, 0.1);
        }
        
        [data-theme="light"] .btn-outline:hover {
            background: rgba(0, 0, 0, 0.05);
        }

        .btn-primary-action {
            background: var(--primary);
            color: var(--primary-invert);
            padding: 0.5rem 1rem;
            border-radius: var(--radius-md);
            font-weight: 600;
            cursor: pointer;
            transition: transform var(--transition-fast);
        }
        .btn-primary-action:hover {
            transform: scale(1.02);
        }

        /* ==========================================================================
           WELCOME SECTION
           ========================================================================== */
        .welcome-header {
            margin: 4rem 0;
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
        }

        .greeting h1 {
            margin-bottom: 0.5rem;
            background: linear-gradient(to right, var(--text-primary), var(--text-secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .greeting .wave {
            display: inline-block;
            animation: wave 2.5s ease-in-out;
            transform-origin: 70% 70%;
        }

        @keyframes wave {
            0% { transform: rotate(0deg); }
            10% { transform: rotate(14deg); }
            20% { transform: rotate(-8deg); }
            30% { transform: rotate(14deg); }
            40% { transform: rotate(-4deg); }
            50% { transform: rotate(10deg); }
            60% { transform: rotate(0deg); }
            100% { transform: rotate(0deg); }
        }

        /* ==========================================================================
           KPI STATS CARDS
           ========================================================================== */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 1.5rem;
            margin-bottom: 4rem;
        }

        .stat-card {
            padding: 1.5rem;
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .stat-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-md);
            border-color: var(--border-strong);
        }

        .stat-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            color: var(--text-secondary);
            font-size: 0.875rem;
            font-weight: 500;
        }

        .stat-icon {
            width: 32px;
            height: 32px;
            border-radius: 8px;
            background: rgba(255,255,255,0.05);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        [data-theme="light"] .stat-icon { background: rgba(0,0,0,0.05); }

        .stat-value {
            font-size: 2rem;
            font-weight: 700;
            line-height: 1;
        }

        .stat-trend {
            font-size: 0.75rem;
            display: flex;
            align-items: center;
            gap: 0.25rem;
        }
        .trend-up { color: var(--success); }
        .trend-down { color: var(--danger); }
        .trend-neutral { color: var(--text-tertiary); }

        /* ==========================================================================
           FORM SYSTEM (PREMIUM INPUTS)
           ========================================================================== */
        .form-section {
            margin-bottom: 4rem;
        }

        .form-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 2rem;
        }

        .form-group-card {
            padding: 2rem;
        }

        .form-group-card h3 {
            border-bottom: 1px solid var(--border-subtle);
            padding-bottom: 1rem;
            margin-bottom: 1.5rem;
        }

        /* Floating Label Inputs */
        .input-wrapper {
            position: relative;
            margin-bottom: 1.5rem;
        }

        .input-wrapper:last-child {
            margin-bottom: 0;
        }

        .premium-input {
            width: 100%;
            background: transparent;
            border: 1px solid var(--border-strong);
            border-radius: var(--radius-md);
            padding: 1.25rem 1rem 0.75rem 1rem;
            color: var(--text-primary);
            /* Important for Mobile to prevent zooming on iOS */
            font-size: 16px;
            font-family: inherit;
            transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
            appearance: none;
        }

        .premium-input:focus {
            outline: none;
            border-color: var(--accent-1);
            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
        }

        .floating-label {
            position: absolute;
            left: 1rem;
            top: 50%;
            transform: translateY(-50%);
            color: var(--text-secondary);
            font-size: 0.95rem;
            pointer-events: none;
            transition: var(--transition-fast);
        }

        .premium-input:focus ~ .floating-label,
        .premium-input:not(:placeholder-shown) ~ .floating-label,
        .premium-input[type="date"] ~ .floating-label,
        .premium-input[type="time"] ~ .floating-label {
            top: 0.75rem;
            font-size: 0.7rem;
            font-weight: 500;
            color: var(--accent-1);
        }

        .premium-input:not(:focus):not(:placeholder-shown) ~ .floating-label {
            color: var(--text-tertiary);
        }

        /* Multi-input rows (Hours/Mins) */
        .input-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1rem;
            margin-bottom: 1.5rem;
        }
        .input-row .input-wrapper { margin-bottom: 0; }

        /* Select styling */
        select.premium-input {
            cursor: pointer;
            background-image: url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23a1a1aa%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C%2Fpolyline%3E%3C%2Fsvg%3E");
            background-repeat: no-repeat;
            background-position: right 1rem center;
            background-size: 1em;
        }
        
        /* Dark mode calendar/time picker icons inverted */
        [data-theme="dark"] input[type="date"]::-webkit-calendar-picker-indicator,
        [data-theme="dark"] input[type="time"]::-webkit-calendar-picker-indicator {
            filter: invert(1);
            opacity: 0.5;
            cursor: pointer;
        }
        [data-theme="dark"] input[type="date"]::-webkit-calendar-picker-indicator:hover,
        [data-theme="dark"] input[type="time"]::-webkit-calendar-picker-indicator:hover {
            opacity: 1;
        }

        /* ==========================================================================
           LIVE PROGRESS BAR & SUBMIT
           ========================================================================== */
        .live-progress-bar {
            position: fixed;
            bottom: 2rem;
            left: 50%;
            transform: translateX(-50%);
            background: var(--bg-surface);
            border: 1px solid var(--border-strong);
            padding: 1rem 1.5rem;
            border-radius: var(--radius-full);
            box-shadow: var(--shadow-lg);
            display: flex;
            align-items: center;
            gap: 2rem;
            z-index: 1000;
            
            -webkit-
            width: 90%;
            max-width: 800px;
        }

        .progress-info {
            display: flex;
            flex-direction: column;
            flex-grow: 1;
            gap: 0.5rem;
        }

        .progress-text {
            display: flex;
            justify-content: space-between;
            font-size: 0.875rem;
            font-weight: 600;
        }

        .progress-track {
            height: 6px;
            background: var(--border-subtle);
            border-radius: var(--radius-full);
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            width: 0%;
            background: var(--gradient-accent);
            border-radius: var(--radius-full);
            transition: width 0s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .btn-submit {
            background: var(--primary);
            color: var(--primary-invert);
            padding: 0.75rem 2rem;
            border-radius: var(--radius-full);
            font-weight: 600;
            font-size: 0.95rem;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
            transition: transform var(--transition-fast);
            box-shadow: var(--shadow-glow);
            position: relative;
            overflow: hidden;
            border: none;
            cursor: pointer;
        }

        .btn-submit:hover {
            transform: scale(1.02);
            box-shadow: 0 0 30px rgba(255,255,255,0.2);
        }
        
        [data-theme="light"] .btn-submit:hover {
            box-shadow: 0 0 30px rgba(0,0,0,0.2);
        }

        .btn-submit:active { transform: scale(0.98); }

        .btn-submit .loader {
            display: none;
            width: 16px; height: 16px;
            border: 2px solid var(--primary-invert);
            border-bottom-color: transparent;
            border-radius: 50%;
            animation: rotation 1s linear infinite;
        }

        @keyframes rotation { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }

        .btn-submit.loading .text { display: none; }
        .btn-submit.loading .loader { display: block; }
        
        .btn-submit.success {
            background: var(--success);
            color: white;
            box-shadow: 0 0 20px rgba(34, 197, 94, 0.4);
        }

        /* ==========================================================================
           UTILITIES & ICONS (INLINE SVG)
           ========================================================================== */
        svg { width: 1.25rem; height: 1.25rem; stroke-width: 2; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; }
        
        /* ==========================================================================
           RESPONSIVE DESIGN (MOBILE OPTIMIZATION)
           ========================================================================== */
        .mobile-only { display: none !important; }
        .desktop-only { display: flex; }

        @media (max-width: 1024px) {
            .stats-grid { grid-template-columns: repeat(2, 1fr); }
            .form-grid { grid-template-columns: 1fr; }
        }

        @media (max-width: 768px) {
            .mobile-only { display: flex !important; }
            .desktop-only { display: none !important; }
            
            .logo-section span { display: none; } /* hide text to save space */
            
            .container { padding: 0 1rem; }
            .nav-links { display: none; }
            
            .nav-actions { gap: 0.5rem; }
            .nav-actions .btn-outline { padding: 0.4rem 0.8rem; font-size: 0.875rem; }
            
            .welcome-header { 
                flex-direction: column; 
                align-items: flex-start; 
                gap: 1rem; 
                margin: 1.5rem 0; 
            }
            
            h1 { font-size: 1.75rem; }
            
            .stats-grid { 
                grid-template-columns: repeat(2, 1fr); 
                gap: 0.75rem;
                margin-bottom: 2rem;
            }
            
            .stat-card { padding: 1rem; }
            .stat-value { font-size: 1.5rem; }
            
            .form-section { margin-bottom: 2rem; }
            .form-group-card { padding: 1rem; }
            
            .input-row { gap: 0.5rem; margin-bottom: 1rem; }
            .input-wrapper { margin-bottom: 1rem; }
            
            .live-progress-bar { 
                width: 100%; 
                max-width: 100%;
                bottom: 0; 
                border-radius: 0;
                border-left: none;
                border-right: none;
                border-bottom: none;
                padding: 0.75rem 1rem; 
                flex-direction: row;
                align-items: center;
                justify-content: space-between;
                gap: 1rem; 
            }
            
            .progress-info { flex-grow: 1; }
            .btn-submit { 
                width: auto; 
                padding: 0.6rem 1rem; 
                font-size: 0.875rem;
            }
        }
        
        @media (max-width: 480px) {
            h1 { font-size: 1.5rem; }
            .stat-value { font-size: 1.25rem; }
        }

