            --border-subtle: rgba(0, 0, 0, 0.06);
            --border-strong: rgba(0, 0, 0, 0.12);
            
            --text-primary: #0f172a;
            --text-secondary: #64748b;
            --text-tertiary: #94a3b8;
            
            --primary: #0f172a;
            --primary-invert: #ffffff;
            
            --shadow-md: 0 8px 24px rgba(0,0,0,0.08);
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background-color: var(--bg-base);
            color: var(--text-primary);
            line-height: 1.5;
            -webkit-font-smoothing: antialiased;
            display: flex;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            padding: 1.5rem;
        }

        body::before {
            content: '';
            position: fixed;
            top: 0; left: 0; width: 100vw; height: 100vh;
            background: radial-gradient(circle at 15% 0%, rgba(59, 130, 246, 0.05) 0%, transparent 40%),
                        radial-gradient(circle at 85% 100%, rgba(139, 92, 246, 0.05) 0%, transparent 40%);
            pointer-events: none;
            z-index: -1;
        }

        a { color: var(--primary); text-decoration: none; transition: var(--transition-fast); }
        a:hover { opacity: 0.8; }
        button { font-family: inherit; cursor: pointer; border: none; background: none; }

        .auth-container {
            width: 100%;
            max-width: 440px;
            background: var(--bg-surface);
            border: 1px solid var(--border-subtle);
            border-radius: var(--radius-lg);
            padding: 2.5rem 2rem;
            box-shadow: var(--shadow-md);
            position: relative;
        }

        .auth-header {
            text-align: center;
            margin-bottom: 2rem;
        }

        .auth-header h1 {
            font-size: 1.5rem;
            font-weight: 600;
            letter-spacing: -0.02em;
            margin-bottom: 0.5rem;
        }

        .auth-header p {
            font-size: 0.875rem;
            color: var(--text-secondary);
        }

        .form-group {
            margin-bottom: 1.25rem;
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1rem;
        }

        .form-label {
            display: block;
            font-size: 0.875rem;
            font-weight: 500;
            margin-bottom: 0.5rem;
            color: var(--text-secondary);
        }

        .form-input {
            width: 100%;
            background: var(--bg-base);
            border: 1px solid var(--border-strong);
            color: var(--text-primary);
            padding: 0.75rem 1rem;
            border-radius: var(--radius-md);
            font-size: 0.875rem;
            transition: transform var(--transition-fast);
            outline: none;
        }

        .form-input:focus {
            border-color: var(--primary);
            box-shadow: 0 0 0 1px var(--primary);
        }

        .form-input::placeholder {
            color: var(--text-tertiary);
        }

        .checkbox-group {
            display: flex;
            align-items: flex-start;
            gap: 0.75rem;
            margin-bottom: 1.5rem;
        }

        .checkbox-group input {
            margin-top: 0.25rem;
            accent-color: var(--primary);
        }

        .checkbox-group label {
            font-size: 0.8125rem;
            color: var(--text-secondary);
        }

        .btn {
            width: 100%;
            padding: 0.875rem;
            border-radius: var(--radius-md);
            font-size: 0.875rem;
            font-weight: 500;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.75rem;
            transition: transform var(--transition-fast);
        }

        .btn-primary {
            background: var(--primary);
            color: var(--primary-invert);
        }
        .btn-primary:hover {
            opacity: 0.9;
            transform: translateY(-1px);
        }

        .btn-google {
            background: var(--bg-base);
            color: var(--text-primary);
            border: 1px solid var(--border-strong);
        }
        .btn-google:hover {
            background: var(--bg-surface-hover);
        }

        .btn-google svg {
            width: 18px;
            height: 18px;
        }

        .divider {
            display: flex;
            align-items: center;
            text-align: center;
            margin: 1.5rem 0;
            color: var(--text-tertiary);
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }
        
        .divider::before,
        .divider::after {
            content: '';
            flex: 1;
            border-bottom: 1px solid var(--border-subtle);
        }
        
        .divider::before { margin-right: 1rem; }
        .divider::after { margin-left: 1rem; }

        .auth-footer {
            text-align: center;
            margin-top: 2rem;
            font-size: 0.875rem;
            color: var(--text-secondary);
        }

        .auth-footer a {
            font-weight: 500;
        }
        
        .error-message {
            color: var(--danger);
            font-size: 0.875rem;
            text-align: center;
            margin-bottom: 1rem;
            display: none;
        }

subscription.html:
        :root {
            /* VIBRANT & CLEAN COLORS */
            --bg-page: #F8FAFC; 
            --text-main: #0F172A; 
            --text-muted: #475569; 
            --text-sub: #64748B;
            --border-light: #CBD5E1; 
            --primary-border: #A5B4FC;
            --bg-card: #FFFFFF;
            
            --brand-blue: #4338CA; 
            --brand-purple: #7C3AED; 
            --brand-green: #059669; 
            
            --free-bg: #FFFFFF;
            --free-pill-bg: #ECFDF5;
            --free-pill-border: #6EE7B7; 
            --free-icon: #059669;
            
            --pro-bg: #FFFFFF;
            --pro-card-border: #818CF8; 
            --pro-pill-bg: #EEF2FF;
            --pro-pill-border: #A5B4FC; 
            --pro-icon: #4338CA;
            
            --shadow-soft: 0 10px 25px rgba(0, 0, 0, 0.05);
            --shadow-card: 0 20px 40px rgba(67, 56, 202, 0.15); 
            
            --radius-xl: 24px;
            --radius-lg: 16px;
            --radius-md: 12px;
            --radius-pill: 100px;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-font-smoothing: antialiased;
        }

        /* Clean solid background */
        body {
            background-color: var(--bg-page);
            color: var(--text-main);
            font-family: 'Inter', sans-serif;
            line-height: 1.5;
            padding: 32px 16px; 
        }

        .container {
            max-width: 1100px;
            margin: 0 auto;
            position: relative;
            z-index: 10;
        }

        svg { display: inline-block; vertical-align: middle; }

        /* --- 1. HERO SECTION --- */
        .hero {
            display: flex;
            flex-direction: column; 
            gap: 40px;
            margin-bottom: 48px;
        }

        .hero-left {
            width: 100%;
            max-width: 560px;
        }

        .top-badge {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            font-size: 0.75rem;
            font-weight: 800;
            text-transform: uppercase;
            color: var(--brand-blue);
            letter-spacing: 0.05em;
            margin-bottom: 20px;
            background: #EEF2FF;
            padding: 6px 12px;
            border-radius: 100px;
            border: 1px solid #C7D2FE;
        }

        .hero h1 {
            font-size: 2.4rem; 
            font-weight: 800;
            line-height: 1.15;
            letter-spacing: -0.02em;
            margin-bottom: 16px;
            color: var(--text-main);
        }

        .hero h1 .gradient-text {
            background: linear-gradient(135deg, #4F46E5, #9333EA);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            display: block;
        }

        .hero .desc {
            font-size: 1rem;
            color: var(--text-muted);
            margin-bottom: 28px;
            line-height: 1.6;
            font-weight: 500;
        }

        .hero-bullets {
            display: flex;
            flex-direction: column;
            gap: 16px;
            margin-bottom: 28px;
        }

        .hero-bullet {
            display: flex;
            align-items: flex-start;
            gap: 12px;
            font-size: 0.95rem;
            color: var(--text-main);
            font-weight: 500;
        }

        .hero-bullet-icon {
            width: 36px; height: 36px; border-radius: 10px;
            display: flex; align-items: center; justify-content: center;
            flex-shrink: 0; border: 1px solid;
        }
        .icon-green { background: var(--free-pill-bg); color: var(--free-icon); border-color: var(--free-pill-border); }
        .icon-purple { background: var(--pro-pill-bg); color: var(--brand-blue); border-color: var(--pro-pill-border); }

        /* --- 3. PREMIUM DASHBOARD VISUAL (Spaced out Grid with Hub) --- */
        .hero-right {
            width: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        
        .analytics-wrapper {
            position: relative;
            width: 100%;
            max-width: 500px;
            margin: 0 auto;
        }

        /* Dotted Connecting Lines */
        .hub-lines {
            position: absolute;
            top: 0; left: 0;
            width: 100%; height: 100%;
            pointer-events: none;
            z-index: 1;
        }
        
        .hub-lines svg {
            width: 100%;
            height: 100%;
            overflow: visible;
        }
        
        .hub-lines line {
            stroke: #C7D2FE;
            stroke-width: 2;
            stroke-dasharray: 4 6;
        }

        /* 2x2 Grid Layout for Cards */
        .analytics-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 24px;
            position: relative;
            z-index: 2;
            padding: 24px 0;
        }

        /* The Premium Hub in the Center */
        .hub-center {
            position: absolute;
            top: 50%; left: 50%;
            transform: translate(-50%, -50%);
            z-index: 10;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .hub-glow {
            position: absolute;
            width: 70px; height: 70px;
            background: var(--brand-purple);
            filter: blur(20px);
            opacity: 0.5;
            border-radius: 50%;
        }

        .hub-icon {
            width: 56px; height: 56px;
            background: linear-gradient(135deg, #7C3AED, #4338CA);
            border-radius: 50%;
            border: 4px solid var(--bg-page);
            display: flex; justify-content: center; align-items: center;
            color: white;
            box-shadow: 0 8px 20px rgba(67, 56, 202, 0.4);
            position: relative;
            z-index: 2;
        }

        /* Dashboard Mock Cards */
        .mock-card {
            background: var(--bg-card);
            border-radius: var(--radius-lg);
            padding: 16px;
            box-shadow: 0 10px 25px rgba(0,0,0,0.03);
            border: 1px solid var(--border-light);
            display: flex; flex-direction: column; justify-content: center;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
            position: relative;
        }

        .mock-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(67, 56, 202, 0.12);
            border-color: var(--primary-border);
        }
        
        .mc-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
        }

        .mc-title { font-size: 0.85rem; font-weight: 800; color: var(--text-main); margin-bottom: 2px;}
        .mc-sub { font-size: 0.65rem; color: var(--text-sub); font-weight: 600; margin-bottom: 12px; }
        
        .mc-badge {
            font-size: 0.55rem;
            font-weight: 800;
            padding: 2px 6px;
            border-radius: 4px;
            text-transform: uppercase;
        }
        
        .mc-badge.free { background: var(--free-pill-bg); color: var(--brand-green); }
        .mc-badge.pro { background: var(--text-main); color: #FFF; }

        /* Heatmap Specific */
        .heatmap-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; }
        .hm-cell { aspect-ratio: 1; border-radius: 2px; background: #E2E8F0; }
        .hm-cell.lvl-1 { background: #C7D2FE; }
        .hm-cell.lvl-2 { background: #818CF8; }
        .hm-cell.lvl-3 { background: #4F46E5; }
        
        /* Bar Chart */
        .bar-chart-mock { display: flex; align-items: flex-end; justify-content: space-between; height: 50px; gap: 4px;}
        .mock-bar { flex: 1; border-radius: 3px 3px 0 0; background: #CBD5E1; }
        .mock-bar.active { background: var(--brand-blue); }
        .mock-bar.semi { background: #A5B4FC; }

        /* ==============================================================
           COMBINED GRID (Pricing Cards + Feature Pills ALIGNED) 
           ============================================================== */
        .comparison-layout {
            display: flex;
            flex-direction: column;
            gap: 24px;
            margin-bottom: 40px;
        }

        /* Redefine card properties inside the combined layout */
        .card {
            background: var(--free-bg);
            border: 2px solid var(--border-light);
            border-radius: var(--radius-xl);
            padding: 28px 24px; 
            box-shadow: var(--shadow-soft);
            display: flex; flex-direction: column;
            height: 100%;
        }

        .card-pro {
            background: var(--pro-bg);
            border: 3px solid var(--pro-card-border);
            box-shadow: var(--shadow-card);
        }

        .card-header-flex { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; }
        .card-icon {
            width: 48px; height: 48px; border-radius: 12px;
            display: flex; align-items: center; justify-content: center;
            margin-bottom: 16px; border: 1px solid;
        }
        .icon-free-card { background: var(--free-pill-bg); color: var(--brand-green); border-color: var(--free-pill-border); }
        .icon-pro-card { background: var(--pro-pill-bg); color: var(--brand-blue); border-color: var(--pro-pill-border); margin-bottom: 0;}

        .card h2 { font-size: 2rem; font-weight: 800; margin-bottom: 4px; color: var(--text-main); }
        .card p.sub { color: var(--text-muted); font-size: 0.95rem; margin-bottom: 24px; font-weight: 500; }
        
        .price-wrap { margin-bottom: 24px; }
        .price { font-size: 3rem; font-weight: 800; line-height: 1; color: var(--text-main); }
        .price-span { color: var(--text-muted); font-size: 0.95rem; font-weight: 600; margin-top: 8px; }

        .popular-badge {
            background: linear-gradient(135deg, #EEF2FF, #E0E7FF);
            color: var(--brand-blue); font-size: 0.75rem; font-weight: 800;
            padding: 6px 12px; border-radius: var(--radius-pill);
            display: flex; align-items: center; gap: 4px; text-transform: uppercase;
            border: 1px solid var(--pro-card-border);
        }

        .card-list { list-style: none; margin-bottom: 32px; flex: 1; }
        .card-list li {
            display: flex; align-items: center; gap: 12px; margin-bottom: 14px;
            font-size: 0.95rem; font-weight: 600; color: var(--text-main);
        }
        .card-list li svg { flex-shrink: 0; }
        .card-list li svg.check-green { color: var(--brand-green); }
        .card-list li svg.check-purple { color: var(--brand-blue); }

        /* Radios */
        .radio-group { display: flex; flex-direction: column; gap: 14px; margin-bottom: 28px; }
        .radio-label {
            display: flex; align-items: center; justify-content: space-between;
            padding: 16px; border: 2px solid var(--border-light);
            border-radius: var(--radius-md); cursor: pointer;
            background: #FFF; transition: transform 0.2s;
        }
        .radio-label.active { border: 2px solid var(--brand-blue); background: var(--pro-pill-bg); }
        
        .radio-left { display: flex; align-items: center; gap: 10px; }
        .custom-radio {
            width: 20px; height: 20px; border-radius: 50%;
            border: 2px solid #94A3B8; display: flex; align-items: center; justify-content: center;
        }
        .radio-label.active .custom-radio { border-color: var(--brand-blue); }
        .radio-label.active .custom-radio::after {
            content: ''; width: 10px; height: 10px; border-radius: 50%; background: var(--brand-blue);
        }
        
        .radio-text-main { font-weight: 700; font-size: 1rem; display: flex; align-items: center; gap: 6px; color: var(--text-main); flex-wrap: wrap;}
        .save-badge { background: #10B981; color: #FFFFFF; font-size: 0.65rem; padding: 2px 6px; border-radius: 4px; font-weight: 800; white-space: nowrap;}
        .radio-text-sub { font-size: 0.8rem; color: var(--text-muted); font-weight: 500; margin-top: 2px; }
        
        .radio-price { text-align: right; }
        .r-price { font-weight: 800; font-size: 1.15rem; color: var(--text-main); }
        .r-strike { font-size: 0.8rem; color: #64748B; text-decoration: line-through; font-weight: 600; }

        .btn {
            width: 100%; padding: 16px; border-radius: var(--radius-md);
            font-size: 1rem; font-weight: 700; display: flex; align-items: center;
            justify-content: center; gap: 8px; cursor: pointer; transition: transform 0.3s; border: none;
            margin-top: auto; /* Push button to bottom */
        }
        .btn-outline { background: transparent; border: 2px solid var(--text-main); color: var(--text-main); }
        .btn-primary { background: linear-gradient(135deg, #4F46E5, #7C3AED); color: #FFF; box-shadow: 0 8px 20px rgba(79, 70, 229, 0.4); }

        .secure-text { text-align: center; font-size: 0.75rem; color: var(--text-muted); margin-top: 14px; display: flex; justify-content: center; align-items: center; gap: 6px; font-weight: 600; }

        /* Feature Pills Layout Updates */
        .feature-card {
            background: var(--free-bg); border: 2px solid var(--border-light);
            border-radius: var(--radius-xl); padding: 28px 20px; box-shadow: var(--shadow-soft);
            height: 100%;
        }

        .fc-header { display: flex; align-items: center; gap: 14px; margin-bottom: 20px; }
        .fc-icon { width: 40px; height: 40px; border-radius: 10px; display: flex; align-items: center; justify-content: center; border: 1px solid; flex-shrink: 0;}
        .fc-icon-green { background: var(--free-pill-bg); color: var(--brand-green); border-color: var(--free-pill-border); }
        .fc-icon-purple { background: var(--pro-pill-bg); color: var(--brand-blue); border-color: var(--pro-pill-border); }
        
        .fc-title { font-weight: 800; font-size: 1.1rem; color: var(--text-main); line-height: 1.2;}
        .fc-sub { font-size: 0.85rem; color: var(--text-muted); font-weight: 500; margin-top: 4px;}

        .pills-container { display: flex; flex-wrap: wrap; gap: 8px; }

        .pill {
            display: inline-flex; align-items: center; gap: 6px;
            padding: 8px 12px; border-radius: var(--radius-pill);
            font-size: 0.8rem; font-weight: 700; background: #FFF;
        }
        .pill-free { border: 2px solid var(--free-pill-border); color: var(--text-main); }
        .pill-free svg { color: var(--brand-green); width: 14px; stroke-width: 3;}
        
        .pill-pro { border: 2px solid var(--pro-pill-border); color: var(--brand-blue); }
        .pill-pro svg { color: var(--brand-blue); width: 14px; stroke-width: 2.5;}

        /* --- 4. TRUST FOOTER --- */
        .trust-footer {
            border-top: 2px solid var(--border-light);
            padding-top: 32px;
            display: flex;
            flex-direction: column; 
            gap: 24px;
        }
        .trust-item { display: flex; align-items: flex-start; gap: 14px; }
        .trust-item svg { color: var(--brand-blue); width: 28px; height: 28px; flex-shrink: 0;}
        .trust-title { font-weight: 800; font-size: 0.95rem; color: var(--text-main); margin-bottom: 2px; }
        .trust-desc { font-size: 0.85rem; color: var(--text-muted); line-height: 1.4; font-weight: 500;}

        /* ==============================================================
           MEDIA QUERIES FOR DESKTOP / TABLET UPGRADES 
           ============================================================== */
        @media (min-width: 900px) {
            body { padding: 60px 40px; }
            
            .hero { flex-direction: row; align-items: center; justify-content: space-between; margin-bottom: 72px; gap: 40px; }
            .hero-right { flex: 1; justify-content: flex-end; padding: 0;}
            
            .hero h1 { font-size: 3.2rem; }
            
            /* Apply 2x2 grid layout for exact horizontal alignment on larger screens */
            .comparison-layout { 
                display: grid;
                grid-template-columns: 1fr 1fr; 
                gap: 24px; 
            }
            .free-pricing { grid-column: 1; grid-row: 1; }
            .free-features { grid-column: 1; grid-row: 2; }
            .pro-pricing { grid-column: 2; grid-row: 1; }
            .pro-features { grid-column: 2; grid-row: 2; }
            
            .card { padding: 40px; }
            .feature-card { padding: 32px; }
            .pill { padding: 10px 16px; font-size: 0.85rem; }
            
            .trust-footer { flex-direction: row; justify-content: space-between; padding-top: 40px;}
            .trust-item { flex: 1; min-width: 250px; }
        }
